from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r,c) in seen:
                continue
            q = [(r,c)]
            seen.add((r,c))
            cells=[]
            while q:
                y,x=q.pop()
                cells.append((y,x))
                for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx] != bg and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            comps.append(cells)
    candidates=[cells for cells in comps if max(c for r,c in cells) < w-1]
    out=[row[:] for row in grid]
    if candidates:
        cells=max(candidates, key=lambda cs:max(c for r,c in cs))
        right=max(c for r,c in cells)
        for r in range(min(y for y,x in cells), max(y for y,x in cells)+1):
            for c in range(right+1,w):
                out[r][c]=1
    return out
